INSERT OR REPLACE INTO content (key, value, updated_at) VALUES ('concurrentCommitments', '[{"diameter": "2900 MM", "title": "MS Pipeline & Civil Works — Shakkar Pench Micro Lift Irrigation Project", "location": "Chhindwara, Madhya Pradesh", "detail": "Laying of 2900 mm diameter MS rising main pipeline over a length of 12.755 km, together with associated civil works — excavation, backfilling and concrete works — for the Hard Dam under the Shakkar Pench Micro Lift Irrigation Project, as sub-contractor to M/s Adani-LCC JV (Adani Water Limited).", "workOrderValue": "₹ 12.14 Cr", "workDone": "In Progress"}, {"diameter": "2600 MM", "title": "MS Syphon Pipeline — IR014, Mahi Bajaj Sagar", "location": "Banswara, Rajasthan", "detail": "Excavation, laying & jointing of 2600 mm diameter, 16 mm thickness MS Syphon Pipeline for IR014 — Mahi Bajaj Sagar, Banswara, as sub-contractor to M/s SCC Infrastructure Pvt Ltd.", "workOrderValue": "₹ 12 Cr", "workDone": "₹ 1 Cr"}, {"diameter": "3100 MM", "title": "MS Water Twin Pipeline — ISP Kalisindh Ph-I, MLIS", "location": "Dewas, Madhya Pradesh", "detail": "Excavation, laying & jointing of 3100 mm diameter MS Water Twin Pipeline for ISP Kalisindh Ph-I, MLIS Water Pipeline Project, Dewas, MP, as sub-contractor to M/s Larsen & Toubro Limited, Construction Division.", "workOrderValue": "₹ 22 Cr", "workDone": "₹ 19 Cr"}]', datetime('now'));

INSERT OR REPLACE INTO content (key, value, updated_at) VALUES ('home', '{"heroTechTag": "ATF / 001 — ENGINEERING", "heroEyebrow": "Anand Techno-Fab LLP · Ahmedabad, Gujarat", "heroHeadlineLine1": "Engineering Infrastructure.", "heroHeadlineLine2": "Delivering With Precision.", "heroIntro": "Infrastructure development and execution across water pipeline projects, structural fabrication & erection, earthwork, mining and related operations.", "heroCtaPrimaryLabel": "Explore Our Capabilities", "heroCtaPrimaryTo": "/capabilities", "heroCtaSecondaryLabel": "View Projects", "heroCtaSecondaryTo": "/projects", "scrollLabel": "Scroll", "stats": [{"value": "20+", "label": "Years of Field Experience"}, {"value": "20", "label": "Project References in Profile"}, {"value": "145+", "label": "Skilled Contractual Workforce"}, {"value": "3", "label": "ISO Certifications Held"}], "sections": {"about": {"eyebrowIndex": "01", "eyebrowLabel": "About", "heading": "Two decades\nof building\nIndia''s\ninfrastructure.", "body": "We started our journey in 2004 with the name Anand Construction, providing services in water pipeline projects and structural fabrication. With years of experience and sustainable growth, the venture was incorporated as Anand Techno-Fab LLP in 2018 to continue the journey in infrastructure development & solutions across irrigation, structural fabrication & erection, earthwork and mining.", "linkLabel": "Read our full story"}, "services": {"eyebrowIndex": "02", "eyebrowLabel": "Specializations", "heading": "Built for\ncomplex project\nexecution.", "linkLabel": "All services"}, "projects": {"eyebrowIndex": "03", "eyebrowLabel": "Project Experience", "heading": "Selected\nproject experience.", "linkLabel": "View all 20 projects"}, "capability": {"eyebrowIndex": "04", "eyebrowLabel": "Execution Capability", "heading": "A fleet built\nfor scale.", "linkLabel": "View complete equipment"}, "quality": {"eyebrowIndex": "05", "eyebrowLabel": "Quality, Safety & Environment", "heading": "Quality is\nengineered in."}, "photography": {"eyebrowIndex": "06", "eyebrowLabel": "Field Execution", "heading": "Grounded\nin real\nfieldwork.", "linkLabel": "View full gallery", "items": [{"image": "/images/gallery/kalisindh-aerial.jpg", "caption": "Kalisindh Phase-I, MLIS — Dewas, Madhya Pradesh"}, {"image": "/images/gallery/sauni-earthwork.jpg", "caption": "Earthwork Excavation — SAUNI Yojana L3P3, Gujarat"}, {"image": "/images/gallery/mining-jafrabad-1.jpg", "caption": "Mining Operations — Jafrabad, Amreli"}]}, "recognition": {"eyebrowIndex": "07", "eyebrowLabel": "Recognition", "heading": "Recognized by our clients", "linkLabel": "All certifications & awards"}, "finalCta": {"heading": "Have an\ninfrastructure\nproject in mind?", "body": "Let''s discuss your requirement.", "ctaPrimaryLabel": "Start a Conversation", "ctaSecondaryLabel": "WhatsApp Us", "backgroundImage": "/images/gallery/welding-cta.jpg"}}}', datetime('now'));

INSERT OR REPLACE INTO content (key, value, updated_at) VALUES ('pageHeroes', '{"about": {"eyebrow": "About Us", "title": "About Anand Techno-Fab", "intro": "A team of young, dynamic and technically qualified personnel with 20 years of varied experience in infrastructure execution."}, "services": {"eyebrow": "Services", "title": "What We Specialize In", "intro": "We undertake turnkey projects across five core specializations, built on 20 years of varied field experience."}, "projects": {"eyebrow": "Projects", "title": "Project Experience", "intro": "Twenty project references executed for clients including Adani-LCC JV, L&T, LCC Projects Limited, SCC Infrastructure, Kalpataru, JMC and ESSAR."}, "capabilities": {"eyebrow": "Capabilities", "title": "Execution Capacity", "intro": "A dedicated technical team and a fleet of owned heavy machinery, deployed across concurrent project sites."}, "qualitySafety": {"eyebrow": "Quality & Safety", "title": "Quality, Safety & Environment", "intro": "Our operating policies for health, safety, environment and quality management — applied consistently across every project site."}, "certifications": {"eyebrow": "Certifications", "title": "Credentials & Registrations", "intro": "Certification, registration and recognition documents, presented as issued — evidence of an established, compliant enterprise."}, "gallery": {"eyebrow": "Gallery", "title": "Field Photography", "intro": "Real project photography from active and completed sites — pipelines, earthwork, mining and the people executing the work."}, "contact": {"eyebrow": "Contact", "title": "Let''s Discuss Your Project", "intro": "Reach us directly by phone, email or WhatsApp, or send a project enquiry using the form below."}}', datetime('now'));

